import{describe,it,expect,beforeEach}from"vitest";import{achievements,categories,filterAchievements,sortAchievementsByYear,getUniqueStates,getUniqueCategories,toggleBookmark,getBookmarkedIds}from"../../frontend/state-achievements/state-achievements.js";const REQUIRED_ACHIEVEMENT_FIELDS=["id","year","title","state","stateCode","region","category","description","significance","icon"];describe("State Achievements Dataset Integrity",()=>{it("contains at least 25 landmark achievements in the dataset",()=>{expect(achievements.length).toBeGreaterThanOrEqual(25)}),it("every achievement contains all required fields with valid types",()=>{achievements.forEach((e,t)=>{REQUIRED_ACHIEVEMENT_FIELDS.forEach(a=>{expect(e,`Achievement at index ${t} missing field ${a}`).toHaveProperty(a),"year"===a?(expect(typeof e.year).toBe("number"),expect(e.year).toBeGreaterThanOrEqual(1900),expect(e.year).toBeLessThanOrEqual(2030)):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all achievement IDs are unique",()=>{const e=achievements.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)}),it("covers all 7 core achievement categories",()=>{const e=new Set(achievements.map(e=>e.category));expect(e.size).toBe(7),expect(e.has("sports")).toBe(!0),expect(e.has("science")).toBe(!0),expect(e.has("education")).toBe(!0),expect(e.has("economy")).toBe(!0),expect(e.has("literature")).toBe(!0),expect(e.has("technology")).toBe(!0),expect(e.has("environment")).toBe(!0)})}),describe("State Achievements Filtering & Search",()=>{it("returns all achievements when query, state, and category are default",()=>{const e=filterAchievements(achievements);expect(e.length).toBe(achievements.length)}),it("filters achievements by search query (e.g. Nobel or Olympic)",()=>{const e=filterAchievements(achievements,{search:"Nobel"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.title,e.state,e.category,e.description,e.significance,String(e.year)].some(e=>e&&e.toLowerCase().includes("nobel"));expect(t).toBe(!0)})}),it("filters achievements by state (e.g. WB or Kerala)",()=>{const e=filterAchievements(achievements,{state:"WB"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.stateCode.toLowerCase()).toBe("wb")})}),it("filters achievements by category (e.g. science)",()=>{const e=filterAchievements(achievements,{category:"science"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category.toLowerCase()).toBe("science")})}),it("filters by bookmarked items correctly",()=>{const e=["ach-1","ach-5"],t=filterAchievements(achievements,{bookmarkedOnly:!0,bookmarkedIds:e});expect(t.length).toBe(2),t.forEach(t=>{expect(e).toContain(t.id)})}),it("handles invalid inputs gracefully",()=>{expect(filterAchievements(null)).toEqual([]),expect(filterAchievements([])).toEqual([])})}),describe("State Achievements Sorting & Lookups",()=>{it("sorts achievements by year ascending (earliest first)",()=>{const e=sortAchievementsByYear(achievements,"asc");expect(e.length).toBe(achievements.length);for(let t=1;t<e.length;t++)expect(e[t-1].year).toBeLessThanOrEqual(e[t].year)}),it("sorts achievements by year descending (latest first)",()=>{const e=sortAchievementsByYear(achievements,"desc");expect(e.length).toBe(achievements.length);for(let t=1;t<e.length;t++)expect(e[t-1].year).toBeGreaterThanOrEqual(e[t].year)}),it("extracts unique states sorted alphabetically",()=>{const e=getUniqueStates(achievements);expect(e.length).toBeGreaterThan(0);for(let t=1;t<e.length;t++)expect(e[t-1].name.localeCompare(e[t].name)).toBeLessThanOrEqual(0)}),it("extracts unique categories",()=>{const e=getUniqueCategories(achievements);expect(e.length).toBe(7)})}),describe("Bookmark Management Helpers",()=>{beforeEach(()=>{"undefined"!=typeof localStorage&&localStorage.clear()}),it("returns empty array when no bookmarks saved",()=>{expect(getBookmarkedIds()).toEqual([])}),it("handles toggle bookmark when localStorage is present or absent",()=>{expect(typeof toggleBookmark("ach-1")).toBe("boolean")})});